/* =====================================================
   BANCO DE PREGUNTAS — ¿Quién Quiere Ser Millonario?
   Edición Ingeniería de Software
   Formato de cada pregunta:
   { q: enunciado, o: [opciones], c: índice correcta, exp: explicación,
     cat?: 'java'|'db'|'arq'|'prog'|'proj', code?: string }
   ===================================================== */

/* ================= NIVEL FÁCIL ================= */
const EASY=[
 {q:`¿Qué extensión tienen los archivos de código fuente de Java?`,o:[`.class`,`.java`,`.jar`,`.txt`],c:1,exp:`El código fuente se escribe en archivos .java. El compilador javac los transforma en archivos .class que contienen el bytecode que ejecuta la JVM.`},
 {q:`¿Qué palabra clave se usa para crear un objeto nuevo?`,o:[`new`,`create`,`object`,`make`],c:0,exp:`El operador new reserva memoria en el heap y llama al constructor de la clase: Persona p = new Persona();`},
 {q:`¿Cuál es el punto de entrada de una aplicación Java?`,o:[`public void start()`,`static void init()`,`public static void main(String[] args)`,`void run()`],c:2,exp:`La JVM busca el método main con esa firma exacta (public static void main(String[] args)) para arrancar la aplicación.`},
 {q:`¿Cuál de estos es un tipo de dato primitivo en Java?`,o:[`String`,`Integer`,`boolean`,`ArrayList`],c:2,exp:`Java tiene 8 primitivos: byte, short, int, long, float, double, char y boolean. String e Integer son clases (tipos de referencia).`},
 {q:`¿Cómo se escribe un comentario de una sola línea en Java?`,o:[`<!-- comentario -->`,`# comentario`,`// comentario`,`** comentario **`],c:2,exp:`// comenta una línea; /* ... */ sirve para varias líneas y /** ... */ genera documentación Javadoc.`},
 {q:`¿Qué herramienta compila el código fuente Java a bytecode?`,o:[`javac`,`java`,`jvm`,`javadoc`],c:0,exp:`javac genera el bytecode (.class). El comando java lanza la JVM que ejecuta ese bytecode, y javadoc genera la documentación.`},
 {q:`¿Qué imprime este código?`,code:`System.out.println("5" + 3);`,o:[`"53"`,`8`,`Error de compilación`,`NullPointerException`],c:0,exp:`Si uno de los operandos del operador + es un String, se concatena: "5" + 3 produce el String "53".`},
 {q:`¿Cuántos bits ocupa un int en Java?`,o:[`Depende del sistema operativo`,`16 bits`,`32 bits`,`64 bits`],c:2,exp:`En Java los primitivos tienen tamaño fijo e independiente de la plataforma: int siempre ocupa 32 bits (de -2³¹ a 2³¹-1).`},
 {q:`¿Qué operador compara dos valores comprobando si son iguales?`,o:[`=`,`==`,`===`,`=>`],c:1,exp:`= es el operador de asignación; == compara valores. === no existe en Java (es de JavaScript) y => es la flecha de las expresiones lambda.`},
 {q:`¿Qué imprime este código?`,code:`System.out.println(2 + 2 + " Java");`,o:[`4 Java`,`22 Java`,`Java4`,`Error de compilación`],c:0,exp:`Se evalúa de izquierda a derecha: primero 2+2 = 4 (suma de int) y después se concatena con el String: "4 Java".`},
 {q:`¿Qué imprime este código?`,code:`System.out.println("Java" + 2 + 2);`,o:[`Java4`,`Java22`,`4Java`,`Error de compilación`],c:1,exp:`El primer + concatena "Java" con 2 → "Java2"; el segundo concatena "Java2" con 2 → "Java22". Una vez aparece un String, todo concatena.`},
 {q:`¿Con qué símbolo debe terminar cada sentencia en Java?`,o:[`;`,`.`,`,`,`:`],c:0,exp:`Toda sentencia en Java termina en punto y coma (;), por ejemplo: int x = 5; Olvidarlo produce un error de compilación.`},
 {q:`¿Cuál de estos NO es un tipo primitivo?`,o:[`char`,`float`,`double`,`String`],c:3,exp:`String es una clase de java.lang (tipo de referencia). Los primitivos son byte, short, int, long, float, double, char y boolean.`},
 {q:`¿Qué palabra clave devuelve un valor desde un método?`,o:[`return`,`break`,`yield`,`exit`],c:0,exp:`return finaliza el método y devuelve el valor. break sale de un bucle/switch; yield se usa en switch expressions (Java 14+).`},
 {q:`¿Cuál es el resto de la operación 10 % 3?`,o:[`1`,`3`,`0`,`3.33`],c:0,exp:`El operador módulo (%) devuelve el resto de la división entera: 10 = 3·3 + 1, por tanto el resto es 1.`},
 {q:`¿Cuál es la forma correcta de declarar una variable de texto?`,o:[`String nombre = "Ana";`,`string nombre = "Ana";`,`String nombre := "Ana";`,`nombre String = "Ana";`],c:0,exp:`Java distingue mayúsculas y minúsculas: la clase es String (con S mayúscula). La sintaxis es Tipo nombre = valor;`},
 {cat:'db',q:`¿Qué lenguaje se utiliza para consultar y manipular bases de datos relacionales?`,o:[`SQL`,`HTML`,`FTP`,`UML`],c:0,exp:`SQL (Structured Query Language) es el estándar: SELECT, INSERT, UPDATE, DELETE, CREATE TABLE… Cada motor (MySQL, PostgreSQL, Oracle) lo implementa.`},
 {cat:'db',q:`¿Qué sentencia SQL se usa para recuperar datos de una tabla?`,o:[`SELECT`,`GET`,`FETCH`,`EXTRACT`],c:0,exp:`SELECT columnas FROM tabla WHERE condición; es la consulta básica de lectura de datos.`},
 {cat:'db',q:`¿Qué es una PRIMARY KEY (clave primaria)?`,o:[`Un campo que identifica de forma única cada fila de la tabla`,`Un campo que permite valores duplicados`,`Una copia de seguridad de la tabla`,`Un índice opcional sin efecto real`],c:0,exp:`La PRIMARY KEY no admite NULL ni duplicados: identifica cada registro. Ejemplo: id INT PRIMARY KEY.`},
 {cat:'prog',q:`¿Qué estructura de datos sigue el principio LIFO (último en entrar, primero en salir)?`,o:[`Pila (stack)`,`Cola (queue)`,`Conjunto (set)`,`Mapa (map)`],c:0,exp:`Como una pila de platos: se apila y se desapila por arriba (operaciones push/pop). En Java: Deque/Stack.`},
 {cat:'prog',q:`¿Qué estructura sigue el principio FIFO (primero en entrar, primero en salir)?`,o:[`Cola (queue)`,`Pila (stack)`,`Árbol (tree)`,`Grafo (graph)`],c:0,exp:`Como una cola de supermercado: se añade al final (offer/add) y se atiende por el frente (poll/remove). En Java: interfaz Queue.`},
 {cat:'prog',q:`¿Qué es un algoritmo?`,o:[`Una secuencia finita y ordenada de pasos que resuelve un problema`,`Un lenguaje de programación`,`Un tipo de dato numérico`,`Un error en tiempo de ejecución`],c:0,exp:`Es la "receta" que implementa el código: por ejemplo, los pasos para ordenar una lista (quicksort, mergesort…).`},
 {cat:'proj',q:`¿Qué sistema de control de versiones es el estándar actual de la industria?`,o:[`Git`,`FTP`,`Excel`,`Telnet`],c:0,exp:`Git es distribuido y lo usan GitHub, GitLab o Bitbucket. SVN y CVS son sistemas centralizados ya antiguos.`},
 {cat:'proj',q:`¿Qué comando de Git registra los cambios preparados en el historial del repositorio local?`,o:[`git commit`,`git save`,`git push`,`git store`],c:0,exp:`Flujo típico: git add (prepara los cambios), git commit (los registra en el historial) y git push (los sube al remoto).`},
 {cat:'arq',q:`¿Qué patrón separa una aplicación en modelo (datos), vista (presentación) y controlador (lógica)?`,o:[`MVC`,`P2P`,`Cliente-servidor`,`Singleton`],c:0,exp:`Model-View-Controller separa responsabilidades y es la base de muchos frameworks web, como Spring MVC.`},
 {cat:'proj',q:`¿Qué herramienta de construcción y gestión de dependencias es típica en proyectos Java?`,o:[`Maven`,`Tomcat`,`Docker`,`Eclipse`],c:0,exp:`Maven (pom.xml) y Gradle (build.gradle) descargan dependencias y automatizan el build. Tomcat es un servidor y Eclipse un IDE.`},
 {cat:'db',q:`¿Qué cláusula SQL filtra las filas devueltas por una consulta?`,o:[`WHERE`,`WHEN`,`FILTER`,`IF`],c:0,exp:`SELECT * FROM productos WHERE precio > 100; La cláusula WHERE se evalúa antes de agrupar; para filtrar grupos se usa HAVING.`},
 {cat:'db',q:`¿Qué sentencia SQL agrega nuevas filas a una tabla?`,o:[`INSERT INTO`,`ADD ROW`,`CREATE ROW`,`APPEND`],c:0,exp:`INSERT INTO clientes (nombre) VALUES ('Ana'); es la forma estándar de insertar registros.`},
 {cat:'prog',q:`¿Qué es una variable?`,o:[`Un espacio con nombre en memoria que almacena un valor que puede cambiar`,`Un valor constante e inmutable`,`Una instrucción que no se ejecuta`,`Un archivo de configuración`],c:0,exp:`int edad = 25; reserva memoria para un entero. Si la marcas final, su valor no puede cambiar.`},
 {cat:'prog',q:`¿Qué es un bucle?`,o:[`Una estructura que repite un bloque de código mientras se cumpla una condición`,`Una variable que se incrementa sola`,`Un tipo de dato compuesto`,`Un error de compilación`],c:0,exp:`for, while y do-while repiten código. Es clave evitar bucles infinitos controlando bien la condición de salida.`},
 {q:`¿Qué contiene el JDK además de la JRE?`,o:[`El compilador javac y herramientas de desarrollo`,`Solo la máquina virtual`,`Un navegador web`,`El sistema operativo`],c:0,exp:`JDK (Java Development Kit) incluye la JRE (para ejecutar) más javac, jar, javadoc y otras herramientas para desarrollar.`},
 {q:`¿Qué imprime este código?`,code:`int x = 5;
x++;
System.out.println(x);`,o:[`6`,`5`,`4`,`Error de compilación`],c:0,exp:`x++ incrementa la variable en 1 después de su uso. Como no se usa su valor viejo, x pasa de 5 a 6 y luego se imprime.`},
 {q:`¿Qué tipo de dato sirve para almacenar un único carácter?`,o:[`char`,`string`,`Character[]`,`byte`],c:0,exp:`char guarda un solo carácter con comillas simples: char letra = 'A';. Para textos completos se usa String con comillas dobles.`},
 {q:`¿Qué valores puede tomar una variable boolean?`,o:[`true o false`,`0 o 1`,`yes o no`,`null o void`],c:0,exp:`boolean solo admite los literales true y false. Es el tipo de las condiciones en if, while, etc.`},
 {cat:'db',q:`¿Qué sentencia SQL elimina filas de una tabla?`,o:[`DELETE`,`DROP`,`REMOVE`,`CLEAR`],c:0,exp:`DELETE FROM tabla WHERE condición; borra filas. DROP elimina la tabla o base de datos entera, no las filas sueltas.`},
 {cat:'db',q:`¿Qué sentencia SQL crea una nueva tabla?`,o:[`CREATE TABLE`,`INSERT TABLE`,`MAKE TABLE`,`NEW TABLE`],c:0,exp:`CREATE TABLE clientes (id INT PRIMARY KEY, nombre VARCHAR(100)); define la estructura, sus columnas y restricciones.`},
 {cat:'db',q:`¿Qué cláusula SQL ordena los resultados de una consulta?`,o:[`ORDER BY`,`SORT BY`,`GROUP BY`,`ARRANGE`],c:0,exp:`SELECT * FROM productos ORDER BY precio DESC; ordena ascendentemente (ASC) por defecto o descendente (DESC).`},
 {cat:'db',q:`¿Qué función SQL cuenta el número de filas?`,o:[`COUNT(*)`,`SUM(*)`,`TOTAL(*)`,`NUMBER(*)`],c:0,exp:`SELECT COUNT(*) FROM pedidos; devuelve cuántas filas cumplen la condición. SUM solo funciona sobre columnas numéricas.`},
 {cat:'prog',q:`¿Qué operador lógico devuelve true solo si AMBAS condiciones son true?`,o:[`&& (AND)`,`|| (OR)`,`! (NOT)`,`== (igualdad)`],c:0,exp:`true && false es false. El OR (||) devuelve true si al menos una es true, y el NOT (!) invierte el valor.`},
 {cat:'prog',q:`¿Qué operador lógico devuelve true si AL MENOS UNA condición es true?`,o:[`|| (OR)`,`&& (AND)`,`! (NOT)`,`!= (distinto)`],c:0,exp:`false || true es true. El AND (&&) exige que todas sean true y el NOT (!) invierte el resultado.`},
 {cat:'arq',q:`¿Qué es el frontend de una aplicación web?`,o:[`La interfaz de usuario que se ejecuta en el navegador`,`La base de datos del servidor`,`El sistema operativo del hosting`,`El firewall de red`],c:0,exp:`El frontend (HTML, CSS, JavaScript) es lo que ve e interactúa el usuario; el backend procesa datos y lógica en el servidor.`},
 {cat:'proj',q:`¿Qué comando de Git descarga por primera vez un repositorio remoto?`,o:[`git clone`,`git pull`,`git fetch`,`git checkout`],c:0,exp:`git clone copia el repositorio completo a tu equipo. git pull trae cambios cuando ya tienes un clon local.`},
 {cat:'proj',q:`¿Qué comando de Git sube tus commits al repositorio remoto?`,o:[`git push`,`git commit`,`git add`,`git init`],c:0,exp:`git push envía los commits locales confirmados al remoto. Antes debes hacer git add y git commit para registrarlos.`},
 {cat:'proj',q:`¿Qué comando de Git lista las ramas del repositorio?`,o:[`git branch`,`git tree`,`git list`,`git log`],c:0,exp:`git branch muestra las ramas locales. Con -a también las remotas. Para crear una: git branch nombre-rama.`},
 {cat:'java',q:`¿Qué palabra clave se usa para declarar una constante en Java?`,o:[`final`,`const`,`static`,`let`],c:0,exp:`final impide reasignar la variable: final int MAX = 10;. static la convierte en miembro de clase, no en constante.`},
 {cat:'java',q:`¿Qué operador se usa para comparar si dos números son distintos?`,o:[`!=`,`<>`,`!==`,`><`],c:0,exp:`!= devuelve true si los operandos son diferentes. == comprueba igualdad y = es asignación.`},
 {cat:'java',q:`¿Cuál es la extensión de un archivo de bytecode compilado en Java?`,o:[`.class`,`.java`,`.jar`,`.exe`],c:0,exp:`javac convierte el .java en .class con bytecode. El .jar empaqueta varios .class y recursos.`},
 {cat:'db',q:`¿Qué sentencia SQL modifica la estructura de una tabla (añadir columna)?`,o:[`ALTER TABLE`,`UPDATE`,`MODIFY TABLE`,`INSERT`],c:0,exp:`ALTER TABLE clientes ADD email VARCHAR(100); cambia la estructura. UPDATE modifica datos, no columnas.`},
 {cat:'db',q:`¿Qué tipo de datos SQL almacena números enteros?`,o:[`INTEGER`,`VARCHAR`,`DATE`,`FLOAT`],c:0,exp:`INTEGER/INT guarda enteros. VARCHAR guarda texto, DATE fechas y FLOAT números decimales aproximados.`},
 {cat:'prog',q:`¿Qué estructura de control ejecuta un bloque solo si una condición es verdadera?`,o:[`if`,`for`,`while`,`switch`],c:0,exp:`if (condición) { ... } ejecuta el bloque solo cuando la condición se evalúa a true.`},
 {cat:'prog',q:`¿Qué es un array en programación?`,o:[`Una colección de elementos del mismo tipo almacenados en posiciones contiguas`,`Un tipo de dato decimal`,`Un bucle repetitivo`,`Un operador de comparación`],c:0,exp:`Un array guarda N elementos indexados desde 0. En Java: int[] nums = new int[5];`},
 {cat:'proj',q:`¿Qué comando de Git prepara un archivo para el commit?`,o:[`git add`,`git stage`,`git commit`,`git push`],c:0,exp:`git add archivo mueve los cambios al área de staging; después git commit los registra en el historial.`},
 {cat:'arq',q:`¿Qué es el backend de una aplicación web?`,o:[`La parte que procesa datos y lógica en el servidor`,`La interfaz visible en el navegador`,`El archivo CSS de estilos`,`El navegador del usuario`],c:0,exp:`El backend (APIs, bases de datos, lógica de negocio) se ejecuta en el servidor y responde a las peticiones del frontend.`},
 {cat:'java',q:`¿Qué método se usa para imprimir texto en consola en Java?`,o:[`System.out.println()`,`console.log()`,`print()`,`echo`],c:0,exp:`System.out.println("texto") imprime con salto de línea. System.out.print no añade salto.`},
 {cat:'java',q:`¿Qué bucle se usa cuando se conoce de antemano el número de iteraciones?`,o:[`for`,`while`,`do-while`,`foreach`],c:0,exp:`for (int i=0; i<n; i++) es ideal con contador explícito. while se usa cuando la condición depende de un factor externo.`},
 {cat:'db',q:`¿Qué cláusula SQL se usa para agrupar filas y aplicar funciones de agregado?`,o:[`GROUP BY`,`ORDER BY`,`WHERE`,`LIMIT`],c:0,exp:`SELECT categoria, COUNT(*) FROM productos GROUP BY categoria; agrupa por categoría antes de calcular agregados.`},
 {cat:'db',q:`¿Qué cláusula SQL limita el número de filas devueltas en MySQL/PostgreSQL?`,o:[`LIMIT`,`TOP`,`MAX`,`ONLY`],c:0,exp:`SELECT * FROM tabla LIMIT 10; devuelve solo 10 filas. SQL Server usa TOP en su lugar.`},
 {cat:'prog',q:`¿Qué es una función en programación?`,o:[`Un bloque de código reutilizable con nombre que puede recibir parámetros y devolver un valor`,`Una variable global`,`Un tipo de dato numérico`,`Un archivo de configuración`],c:0,exp:`Las funciones evitan duplicar código: int suma(int a, int b){ return a+b; }`},
 {cat:'prog',q:`¿Qué tipo de bucle se usa para recorrer todos los elementos de una colección?`,o:[`for-each`,`do-while`,`goto`,`switch`],c:0,exp:`for (String s : lista) { ... } recorre cada elemento sin necesidad de índice.`},
 {cat:'proj',q:`¿Qué comando de Git muestra el estado de los archivos modificados?`,o:[`git status`,`git show`,`git list`,`git check`],c:0,exp:`git status muestra archivos modificados, preparados o sin seguimiento en el repositorio.`},
 {cat:'arq',q:`¿Qué significa la sigla HTML?`,o:[`HyperText Markup Language`,`HyperTool Modern Language`,`HighText Markup Language`,`Hyperlink Text Mode Language`],c:0,exp:`HTML es el lenguaje de marcado que estructura el contenido de las páginas web.`},
 {cat:'arq',q:`¿Qué tecnología se usa para dar estilos a una página web?`,o:[`CSS`,`SQL`,`FTP`,`JSON`],c:0,exp:`CSS (Cascading Style Sheets) define colores, fuentes, márgenes y disposición de los elementos HTML.`},
 {cat:'java',q:`¿Qué palabra clave se usa para definir una clase en Java?`,o:[`class`,`struct`,`object`,`define`],c:0,exp:`public class Persona { ... } define una clase. struct es de C y object es una instancia, no una declaración.`}
];

/* ================= NIVEL MEDIO ================= */
const MED=[
 {q:`¿Qué significan las siglas JVM?`,o:[`Java Virtual Machine`,`Java Variable Method`,`Just-in-time Virtual Memory`,`Java Verified Module`],c:0,exp:`La Java Virtual Machine ejecuta el bytecode y es la clave de que Java sea "write once, run anywhere".`},
 {q:`¿Qué palabra clave se usa para que una clase herede de otra?`,o:[`implements`,`extends`,`inherits`,`super`],c:1,exp:`extends establece herencia entre clases; implements se usa para implementar interfaces. Java solo permite herencia simple de clases.`},
 {q:`¿Cuál de estos NO es un pilar de la Programación Orientada a Objetos?`,o:[`Encapsulamiento`,`Herencia`,`Compilación`,`Polimorfismo`],c:2,exp:`Los pilares de la POO son encapsulamiento, herencia, polimorfismo y abstracción. La compilación es solo una fase de construcción del programa.`},
 {q:`¿Qué modificador de acceso restringe el acceso únicamente a la propia clase?`,o:[`public`,`protected`,`private`,`default (sin modificador)`],c:2,exp:`private: solo la propia clase. default (sin modificador): mismo paquete. protected: mismo paquete + subclases. public: todo el mundo.`},
 {q:`¿Qué estructura de control se ejecuta al menos una vez siempre?`,o:[`for`,`while`,`do-while`,`for-each`],c:2,exp:`do { ... } while(condición); evalúa la condición DESPUÉS de ejecutar el bloque, por lo que el cuerpo se ejecuta como mínimo una vez.`},
 {q:`¿Cuál es la superclase de todas las clases en Java?`,o:[`Class`,`Object`,`Base`,`Super`],c:1,exp:`Todas las clases heredan implícitamente de java.lang.Object, que aporta toString(), equals(), hashCode(), etc.`},
 {q:`¿Qué hace el Garbage Collector (recolector de basura)?`,o:[`Cierra la consola automáticamente`,`Libera la memoria de los objetos sin referencias`,`Elimina archivos temporales del disco`,`Borra variables duplicadas`],c:1,exp:`El GC detecta objetos inalcanzables y libera su memoria del heap. System.gc() solo sugiere una recogida, nunca la garantiza.`},
 {q:`¿Qué imprime este código?`,code:`System.out.println(7 / 2);`,o:[`3.5`,`3`,`4`,`Error de compilación`],c:1,exp:`7 y 2 son int, así que la división es entera y se trunca: 3. Para obtener 3.5 usa 7.0 / 2 o (double) 7 / 2.`},
 {q:`¿Qué palabra clave impide que una variable vuelva a ser asignada?`,o:[`final`,`const`,`static`,`immutable`],c:0,exp:`final convierte la variable en constante tras su primera asignación. "const" existe como palabra reservada pero no se usa en Java.`},
 {q:`¿Qué devuelve "Hola".length()?`,o:[`3`,`4`,`5`,`Lanza una excepción`],c:1,exp:`length() cuenta los caracteres del String: H-o-l-a = 4. Ojo: en los arrays se usa la propiedad .length (sin paréntesis).`},
 {q:`¿Para qué sirve un constructor de clase?`,o:[`Inicializar el estado del objeto al crearlo`,`Destruir el objeto y liberar su memoria`,`Declarar métodos estáticos`,`Convertir el objeto a String`],c:0,exp:`El constructor tiene el mismo nombre que la clase y no tiene tipo de retorno. Se invoca con new: Persona p = new Persona();`},
 {q:`¿Qué es el encapsulamiento?`,o:[`Ocultar el estado interno y exponer el acceso mediante métodos`,`Agrupar todas las clases en un único paquete`,`Hacer públicos todos los atributos`,`Impedir que una clase tenga herencia`],c:0,exp:`Se logra con atributos private y métodos públicos getters/setters, protegiendo la integridad de los datos del objeto.`},
 {q:`¿Qué hace la sentencia break dentro de un bucle?`,o:[`Sale inmediatamente del bucle`,`Salta a la siguiente iteración`,`Pausa el bucle un segundo`,`Reinicia el bucle desde cero`],c:0,exp:`break termina el bucle (o switch) al instante; continue salta directamente a la siguiente iteración sin ejecutar el resto del cuerpo.`},
 {q:`¿Cuál es la diferencia principal entre un array y un ArrayList?`,o:[`El array tiene tamaño fijo; el ArrayList puede crecer y encoger`,`ArrayList solo almacena String`,`El array crece dinámicamente`,`ArrayList es un tipo primitivo`],c:0,exp:`Un array (int[] a = new int[5]) no cambia de tamaño; ArrayList<E> es una colección dinámica de la API de Java (java.util).`},
 {q:`¿Qué es el autoboxing?`,o:[`Conversión automática entre primitivos y sus wrappers (int ↔ Integer)`,`Anidar una clase dentro de otra`,`Convertir double a int sin pérdida`,`Empaquetar la aplicación en un .jar`],c:0,exp:`Ejemplo: List<Integer> lista; lista.add(5); el 5 se convierte solo a Integer.valueOf(5). El proceso inverso se llama unboxing.`},
 {q:`¿Qué palabra clave usa una clase para implementar una interfaz?`,o:[`implements`,`extends`,`inherits`,`instanceof`],c:0,exp:`Una clase puede implements varias interfaces a la vez (separadas por comas), pero solo puede extends una clase: herencia simple.`},
 {q:`¿Cuál es el valor por defecto de un atributo boolean de una clase?`,o:[`false`,`true`,`null`,`No tiene: da error de compilación`],c:0,exp:`Los atributos se inicializan solos: numéricos a 0, boolean a false y referencias a null. Las variables locales, en cambio, no tienen valor por defecto.`},
 {q:`¿Qué indica void en la firma de un método?`,o:[`Que el método no devuelve ningún valor`,`Que el método es estático`,`Que el método no recibe parámetros`,`Que el método es privado`],c:0,exp:`void significa "sin valor de retorno". Los parámetros van entre paréntesis y son independientes del tipo de retorno.`},
 {q:`¿Qué es una clase wrapper (envoltorio)?`,o:[`Una clase que envuelve un primitivo como objeto (Integer, Double, Boolean…)`,`Una clase sin constructores`,`Una clase que hereda de Exception`,`Una clase anónima dentro de un método`],c:0,exp:`Los wrappers permiten usar primitivos donde se exigen objetos (colecciones, genéricos): Integer, Long, Double, Character, Boolean…`},
 {q:`¿Qué excepción se lanza al acceder al índice 7 de un array de 3 elementos?`,o:[`ArrayIndexOutOfBoundsException`,`NullPointerException`,`ClassCastException`,`ArithmeticException`],c:0,exp:`El índice está fuera del rango válido (0..2). NullPointerException ocurre al usar una referencia null; ClassCastException al hacer un cast inválido.`},
 {cat:'db',q:`¿Qué es una FOREIGN KEY (clave foránea)?`,o:[`Un campo que referencia a la PRIMARY KEY de otra tabla, garantizando integridad referencial`,`Una clave cifrada con contraseña`,`Un índice para acelerar consultas`,`Una PRIMARY KEY duplicada en la misma tabla`],c:0,exp:`Ejemplo: pedidos.cliente_id REFERENCES clientes(id). Impide guardar pedidos de clientes que no existen.`},
 {cat:'db',q:`¿Qué significan las siglas ACID en transacciones?`,o:[`Atomicidad, Consistencia, Aislamiento y Durabilidad`,`Acceso, Control, Identidad y Datos`,`Atomicidad, Cifrado, Integridad y Despliegue`,`Asociación, Consulta, Índice y División`],c:0,exp:`Una transacción se aplica entera o no se aplica: si algo falla, se hace rollback y la BD queda consistente.`},
 {cat:'db',q:`¿Qué sentencia SQL modifica datos ya existentes en una tabla?`,o:[`UPDATE`,`ALTER`,`MODIFY`,`CHANGE`],c:0,exp:`UPDATE tabla SET campo = valor WHERE condición; ALTER modifica la ESTRUCTURA de la tabla (DDL), no sus datos.`},
 {cat:'db',q:`¿Qué hace una cláusula JOIN?`,o:[`Combina filas de dos o más tablas según una condición de relación`,`Duplica una tabla completa`,`Elimina filas repetidas`,`Ordena los resultados alfabéticamente`],c:0,exp:`SELECT ... FROM pedidos JOIN clientes ON pedidos.cliente_id = clientes.id; relaciona datos repartidos en varias tablas.`},
 {cat:'arq',q:`¿Qué principio SOLID indica que una clase debe tener una única responsabilidad?`,o:[`SRP (Single Responsibility Principle)`,`OCP (Open/Closed)`,`LSP (Sustitución de Liskov)`,`DIP (Inversión de dependencias)`],c:0,exp:`Si una clase hace varias cosas tendrá varios motivos para cambiar: conviene separar responsabilidades en clases distintas.`},
 {cat:'arq',q:`¿Qué patrón garantiza que una clase tenga una única instancia con acceso global?`,o:[`Singleton`,`Factory`,`Observer`,`Builder`],c:0,exp:`Constructor privado + instancia estática. Útil para configuración o pools; cuidado: dificulta los tests unitarios.`},
 {cat:'arq',q:`¿Qué es una API REST?`,o:[`Un estilo arquitectónico para servicios web basado en HTTP, verbos y recursos`,`Un lenguaje de programación`,`Una base de datos NoSQL`,`Un framework de Java`],c:0,exp:`GET consulta, POST crea, PUT/PATCH actualiza y DELETE elimina; las respuestas suelen ser JSON.`},
 {cat:'proj',q:`En un proyecto Maven/Gradle estándar, ¿dónde va el código fuente Java?`,o:[`src/main/java`,`source/code`,`java/src`,`bin/main`],c:0,exp:`Convención: src/main/java para el código, src/main/resources para recursos y src/test/java para los tests.`},
 {cat:'proj',q:`¿Para qué sirve el archivo .gitignore?`,o:[`Indicar a Git qué archivos o carpetas NO debe versionar`,`Borrar el repositorio remoto`,`Ignorar errores de compilación`,`Ocultar ramas a otros usuarios`],c:0,exp:`Típico: target/, .idea/, node_modules/, *.class o archivos con credenciales. Evita subir basura o secretos al repo.`},
 {cat:'prog',q:`¿Qué es la recursividad?`,o:[`Una función o método que se llama a sí mismo; necesita un caso base para terminar`,`Un bucle for optimizado por la JVM`,`Un tipo de excepción`,`Una estructura de datos jerárquica`],c:0,exp:`Ejemplo: factorial(n) = n * factorial(n-1) con caso base factorial(0) = 1. Sin caso base: StackOverflowError.`},
 {cat:'prog',q:`¿Cuál es la complejidad media de buscar una clave en un HashMap?`,o:[`O(1)`,`O(n)`,`O(log n)`,`O(n log n)`],c:0,exp:`Gracias a la función hash el acceso es constante en promedio; con colisiones totales degrada a O(n) (Java 8 usa árboles y queda O(log n)).`},
 {cat:'arq',q:`¿Qué patrón crea objetos sin exponer al cliente la lógica de creación?`,o:[`Factory`,`Observer`,`Singleton`,`Adapter`],c:0,exp:`Una clase factoría encapsula la instanciación: Figura f = FactoriaFiguras.crear("circulo"); desacopla al cliente de las clases concretas.`},
 {cat:'java',q:`¿Qué es un paquete (package) en Java?`,o:[`Un espacio de nombres que agrupa clases relacionadas`,`Una clase sellada`,`Un tipo de variable global`,`Un archivo JAR ejecutable`],c:0,exp:`package com.miempresa.app; agrupa clases y evita colisiones de nombres. Se importa con import.`},
 {cat:'java',q:`¿Qué diferencia hay entre int e Integer?`,o:[`int es primitivo e Integer es su clase wrapper`,`Son exactamente iguales`,`Integer ocupa menos memoria que int`,`int puede ser null`],c:0,exp:`int no puede ser null ni usarse en genéricos; Integer sí. El autoboxing convierte entre ambos automáticamente.`},
 {cat:'java',q:`¿Qué hace el operador ternario (?:)?`,o:[`Evalúa una condición y devuelve uno de dos valores`,`Declara tres variables a la vez`,`Une tres Strings`,`Invierte un boolean`],c:0,exp:`int mayor = a > b ? a : b; devuelve a si la condición es true y b si es false.`},
 {cat:'db',q:`¿Qué es NULL en SQL?`,o:[`Un valor desconocido o ausente`,`El número cero`,`Una cadena vacía`,`El valor false`],c:0,exp:`NULL no es igual a 0 ni a ''; para comprobarlo se usa IS NULL, nunca = NULL.`},
 {cat:'db',q:`¿Qué operador lógico combina condiciones en WHERE?`,o:[`AND y OR`,`+ y -`,`= y ==`,`IF y ELSE`],c:0,exp:`SELECT * FROM t WHERE edad > 18 AND ciudad = 'Madrid'; combina varias condiciones de filtrado.`},
 {cat:'prog',q:`¿Qué es una lista enlazada (LinkedList)?`,o:[`Una secuencia de nodos conectados por referencias al siguiente`,`Un array de tamaño fijo`,`Un mapa de pares clave-valor`,`Un árbol binario`],c:0,exp:`Cada nodo guarda un dato y una referencia al siguiente. Inserta y borra rápido en los extremos, pero acceder por índice es O(n).`},
 {cat:'prog',q:`¿Qué es una variable local?`,o:[`Una variable declarada dentro de un método o bloque`,`Un atributo de clase`,`Una constante global`,`Un parámetro de la JVM`],c:0,exp:`Solo existe mientras se ejecuta el bloque donde se declaró y no tiene valor por defecto.`},
 {cat:'proj',q:`¿Qué comando de Git crea una nueva rama?`,o:[`git branch nombre`,`git new nombre`,`git create nombre`,`git add nombre`],c:0,exp:`git branch feature crea una rama; git checkout -b feature la crea y cambia a ella de una vez.`},
 {cat:'proj',q:`¿Qué comando de Git fusiona una rama en la actual?`,o:[`git merge nombre`,`git combine nombre`,`git union nombre`,`git join nombre`],c:0,exp:`git merge feature integra los cambios de la rama feature en la rama actual.`},
 {cat:'arq',q:`¿Qué es una API (Application Programming Interface)?`,o:[`Un contrato que define cómo interactúan componentes de software`,`Un tipo de base de datos`,`Un sistema operativo`,`Un lenguaje de consultas`],c:0,exp:`Define métodos, parámetros y formatos para que unas piezas de código usen las funcionalidades de otras.`},
 {cat:'java',q:`¿Qué significan las siglas JDK?`,o:[`Java Development Kit`,`Java Database Kernel`,`Java Design Kit`,`Java Debugger Kit`],c:0,exp:`El JDK incluye el compilador javac, la JRE y herramientas de desarrollo para programar en Java.`},
 {cat:'java',q:`¿Qué palabra clave se usa para heredar de una interfaz en otra interfaz?`,o:[`extends`,`implements`,`inherits`,`super`],c:0,exp:`Una interfaz puede extends otra interfaz. Una clase implements las interfaces.`},
 {cat:'db',q:`¿Qué sentencia SQL se usa para cambiar el valor de una fila?`,o:[`UPDATE`,`ALTER`,`CHANGE`,`SET`],c:0,exp:`UPDATE clientes SET nombre='Ana' WHERE id=1; modifica datos existentes. ALTER cambia la estructura.`},
 {cat:'prog',q:`¿Qué es la complejidad algorítmica?`,o:[`Una medida de cómo crece el tiempo o memoria según el tamaño de la entrada`,`La cantidad de líneas de código`,`El número de bugs del programa`,`La velocidad del compilador`],c:0,exp:`Notación Big-O: O(1), O(log n), O(n), O(n log n), O(n²)... Describe el comportamiento asintótico del algoritmo.`},
 {cat:'java',q:`¿Qué hace el método equals() de Object por defecto?`,o:[`Compara referencias (misma identidad de objeto)`,`Compara el contenido de los campos`,`Lanza una excepción`,`Devuelve siempre true`],c:0,exp:`Object.equals() usa ==. Por eso se sobrescribe en clases como String para comparar contenido.`},
 {cat:'java',q:`¿Qué es una clase abstracta?`,o:[`Una clase que no puede instanciarse y puede contener métodos abstractos sin cuerpo`,`Una clase final sin herencia`,`Una interfaz con métodos static`,`Un primitivo numérico`],c:0,exp:`Se declara con abstract y se hereda: las subclases concretas implementan los métodos abstractos.`},
 {cat:'java',q:`¿Qué es un método abstracto?`,o:[`Un método declarado sin cuerpo que las subclases deben implementar`,`Un método final`,`Un método static de utilidad`,`Un método sincronizado`],c:0,exp:`abstract void dibujar(); no tiene implementación. Una clase con métodos abstractos debe ser abstracta.`},
 {cat:'java',q:`¿Qué es el casting en Java?`,o:[`Convertir un valor de un tipo a otro de forma explícita o implícita`,`Crear un objeto nuevo`,`Sobrescribir un método`,`Lanzar una excepción`],c:0,exp:`int n = (int) 3.14; es un cast explícito. El casting entre objetos debe respetar la jerarquía de herencia.`},
 {cat:'db',q:`¿Qué significa la restricción NOT NULL?`,o:[`La columna no admite valores NULL`,`La columna solo admite números positivos`,`La tabla no admite registros`,`La columna es clave foránea`],c:0,exp:`nombre VARCHAR(100) NOT NULL obliga a proporcionar un valor al insertar o actualizar.`},
 {cat:'db',q:`¿Qué sentencia SQL elimina una tabla completa junto con su estructura?`,o:[`DROP TABLE`,`DELETE FROM`,`TRUNCATE`,`REMOVE`],c:0,exp:`DROP TABLE clientes; borra la tabla y su estructura. DELETE borra filas; TRUNCATE vacía la tabla conservando la estructura.`},
 {cat:'db',q:`¿Qué hace la función SQL UPPER()?`,o:[`Convierte un texto a mayúsculas`,`Cuenta las filas`,`Redondea un número`,`Une dos tablas`],c:0,exp:`SELECT UPPER(nombre) FROM clientes; devuelve el texto en mayúsculas. LOWER() lo convierte a minúsculas.`},
 {cat:'prog',q:`¿Qué es la depuración (debugging)?`,o:[`Proceso de encontrar y corregir errores en el código`,`Compilar el programa`,`Escribir documentación`,`Desplegar la aplicación`],c:0,exp:`Se usan breakpoints, inspección de variables y trazas para localizar la causa raíz de los fallos.`},
 {cat:'prog',q:`¿Qué es un caso base en recursividad?`,o:[`La condición que detiene las llamadas recursivas`,`El primer bucle del programa`,`Una variable global`,`El punto de entrada main`],c:0,exp:`Sin caso base la recursión nunca termina y provoca StackOverflowError.`},
 {cat:'proj',q:`¿Qué comando de Git muestra el historial de commits?`,o:[`git log`,`git history`,`git show all`,`git commits`],c:0,exp:`git log lista los commits con autor, fecha y mensaje. git log --oneline lo resume en una línea por commit.`},
 {cat:'proj',q:`¿Qué comando de Git descarta los cambios no preparados de un archivo?`,o:[`git checkout -- archivo`,`git discard archivo`,`git reset archivo`,`git undo archivo`],c:0,exp:`git checkout -- archivo revierte el archivo al último commit. git reset modifica el área de staging.`},
 {cat:'arq',q:`¿Qué es un framework?`,o:[`Un conjunto de bibliotecas y convenciones que estructuran el desarrollo`,`Un lenguaje de programación`,`Un servidor web`,`Un protocolo de red`],c:0,exp:`Spring, Django o Angular imponen una arquitectura y aportan utilidades para no reinventar la rueda.`},
 {cat:'arq',q:`¿Qué significa la sigla MVC?`,o:[`Modelo-Vista-Controlador`,`Máquina-Virtual-Compilador`,`Módulo-Variable-Clase`,`Método-Valor-Constante`],c:0,exp:`Separa datos (modelo), presentación (vista) y lógica (controlador) para organizar el código.`}
];

/* ================= NIVEL DIFÍCIL ================= */
const HARD=[
 {q:`¿Cuál es la diferencia principal entre == y equals() en objetos?`,o:[`Son exactamente equivalentes`,`== compara referencias; equals() compara contenido si está sobrescrito`,`equals() solo existe en la clase String`,`== compara el contenido de los objetos`],c:1,exp:`== compara si dos referencias apuntan al mismo objeto. equals() en Object también compara referencias, pero clases como String lo sobrescriben para comparar contenido.`},
 {q:`¿Qué efecto tiene declarar un método como final?`,o:[`Lo hace privado`,`Impide que las subclases lo sobrescriban`,`Libera su memoria al terminar`,`Lo convierte en abstracto`],c:1,exp:`Un método final no puede sobrescribirse en subclases, garantizando que su comportamiento no cambie. Una clase final no puede tener subclases (p. ej. String).`},
 {q:`¿Qué colección mantiene el orden de inserción y permite duplicados?`,o:[`HashSet`,`HashMap`,`ArrayList`,`TreeSet`],c:2,exp:`Las implementaciones de List (ArrayList, LinkedList) conservan el orden de inserción y admiten duplicados. Los Set no permiten duplicados.`},
 {q:`¿Qué caracteriza a una excepción checked (verificada)?`,o:[`Es un error de sintaxis detectado por el compilador`,`El compilador obliga a manejarla con try/catch o declararla con throws`,`Solo puede ocurrir en tiempo de ejecución`,`No puede capturarse nunca`],c:1,exp:`Ejemplos: IOException, SQLException. Deben manejarse (try/catch) o propagarse (throws). Las RuntimeException (NullPointerException, etc.) son unchecked.`},
 {q:`¿Qué imprime este código?`,code:`String s = "Hola";\ns.concat(" Java");\nSystem.out.println(s);`,o:[`Hola Java`,`Hola`,`Java`,`Lanza una excepción`],c:1,exp:`String es inmutable: concat() devuelve un NUEVO String y no modifica el original. Como el resultado no se asigna, s sigue valiendo "Hola". Lo correcto sería s = s.concat(" Java");`},
 {q:`¿Puede un método static usar la referencia this?`,o:[`Sí, sin restricciones`,`No: this se refiere a la instancia y los métodos static no pertenecen a ninguna`,`Solo si el método es también final`,`Solo dentro de un bucle`],c:1,exp:`this referencia al objeto actual. Los métodos static pertenecen a la clase, no a una instancia, por lo que no pueden usar this ni acceder a miembros no estáticos directamente.`},
 {q:`Desde Java 8, ¿qué pueden incluir las interfaces?`,o:[`Constructores`,`Atributos de instancia`,`Métodos default y static con implementación`,`Herencia de clases`],c:2,exp:`Java 8 añadió métodos default y static con cuerpo. Siguen sin poder tener constructores ni atributos de instancia: sus constantes son public static final.`},
 {q:`Si sobrescribes equals(), ¿qué método debes sobrescribir también para cumplir el contrato?`,o:[`toString()`,`clone()`,`hashCode()`,`compareTo()`],c:2,exp:`Contrato: si a.equals(b) entonces a.hashCode() == b.hashCode(). No respetarlo rompe HashSet y HashMap: objetos "iguales" quedarían en cubetas distintas.`},
 {q:`¿Qué ocurre al compilar este código?`,code:`public void metodo() {\n    int x;\n    System.out.println(x);\n}`,o:[`Imprime 0`,`Error de compilación: variable local sin inicializar`,`Imprime null`,`Lanza NullPointerException`],c:1,exp:`Las variables locales NO tienen valor por defecto: deben inicializarse antes de usarse. Los atributos de clase sí se inicializan solos (int a 0, objetos a null).`},
 {q:`¿Qué es la sobrecarga (overloading) de métodos?`,o:[`Varios métodos con el mismo nombre pero distinta lista de parámetros en la misma clase`,`Redefinir en una subclase un método heredado con la misma firma`,`Llamar a un método desde varios hilos`,`Convertir tipos de dato automáticamente`],c:0,exp:`Overloading: mismo nombre, parámetros distintos (número, tipo u orden) en la misma clase. Redefinir un método heredado con la misma firma es overriding (sobrescritura).`},
 {q:`¿Qué es el polimorfismo?`,o:[`Una referencia de un supertipo apunta a objetos de distintos tipos y cada uno responde según su clase real`,`Declarar varias variables con el mismo nombre`,`Que un método se llama a sí mismo`,`Convertir un double en int automáticamente`],c:0,exp:`Ejemplo: Animal a = new Perro(); a.sonido() ejecuta la versión de Perro gracias al enlace dinámico (dynamic binding) en tiempo de ejecución.`},
 {q:`¿Qué es una interfaz funcional?`,o:[`Una interfaz con exactamente un método abstracto, utilizable con expresiones lambda`,`Una interfaz con solo métodos default`,`Una interfaz que no puede implementarse`,`Una interfaz cuyos métodos son todos static`],c:0,exp:`Ejemplos: Runnable, Comparator, Predicate, Function. Se marcan con @FunctionalInterface y permiten usar lambdas: () -> System.out.println("hola").`},
 {q:`¿Qué hace la anotación @Override?`,o:[`Verifica en compilación que el método realmente sobrescribe uno de la superclase`,`Hace el método final y privado`,`Mejora el rendimiento en tiempo de ejecución`,`Convierte el método en estático`],c:0,exp:`No es obligatoria, pero si la firma no coincide con ningún método heredado el compilador falla, evitando errores tipográficos silenciosos.`},
 {q:`¿Qué es el type erasure (borrado de tipos) en genéricos?`,o:[`El compilador elimina la información de tipos genéricos y la sustituye por Object o sus límites`,`La JVM borra los genéricos en ejecución con el GC`,`Los genéricos se guardan únicamente en el .java`,`Las clases genéricas no pueden instanciarse`],c:0,exp:`List<String> es simplemente List en tiempo de ejecución. Por eso no se puede hacer new T[] ni instanceof con tipos genéricos parametrizados.`},
 {q:`¿Cuál es la diferencia entre HashMap y Hashtable?`,o:[`Hashtable está sincronizada y no admite null; HashMap no está sincronizada y admite una clave null`,`HashMap está sincronizada y Hashtable no`,`Hashtable admite varias claves null`,`Son idénticas en todo`],c:0,exp:`Hashtable es legado (Java 1.1). Para un solo hilo se prefiere HashMap; para concurrencia real, ConcurrentHashMap.`},
 {q:`¿Qué diferencia hay entre String, StringBuilder y StringBuffer?`,o:[`String es inmutable; StringBuilder es mutable y no sincronizado; StringBuffer es mutable y sincronizado`,`Los tres son inmutables`,`StringBuilder es inmutable y más lento`,`StringBuffer no existe desde Java 8`],c:0,exp:`Para concatenar dentro de bucles usa StringBuilder: evita crear cientos de String intermedios. StringBuffer añade sincronización (más lenta) para varios hilos.`},
 {q:`¿Qué es un thread (hilo) en Java?`,o:[`Un flujo de ejecución independiente; se crea extendiendo Thread o implementando Runnable`,`Una excepción sincronizada`,`Una colección thread-safe`,`Un tipo de variable volatile`],c:0,exp:`thread.start() arranca el hilo y llama a run() internamente. Si llamas a run() directamente, se ejecuta en el hilo actual sin crear ninguno nuevo.`},
 {q:`¿Qué imprime este código?`,code:`System.out.println(new String("abc") == "abc");`,o:[`false`,`true`,`Error de compilación`,`abc`],c:0,exp:`new String("abc") crea un objeto nuevo en el heap, fuera del pool de literales, y == compara referencias. Con equals() daría true.`},
 {q:`¿Qué imprime este código?`,code:`System.out.println("A" + "B" == "AB");`,o:[`true`,`false`,`Error de compilación`,`AB`],c:0,exp:`"A" + "B" es una expresión constante: el compilador la pliega a "AB" en tiempo de compilación y ambos literales comparten la misma entrada del pool de Strings.`},
 {q:`¿Qué hace la palabra clave synchronized en un método?`,o:[`Solo un hilo a la vez puede ejecutarlo sobre el mismo objeto`,`Hace el método más rápido`,`Evita que se lancen excepciones`,`Convierte el método en final`],c:0,exp:`Usa el monitor del objeto (o de la clase si es static) como candado, evitando condiciones de carrera y garantizando visibilidad entre hilos.`},
 {cat:'db',q:`¿Qué es la normalización de una base de datos?`,o:[`Organizar tablas y dependencias para eliminar redundancia y anomalías (1FN, 2FN, 3FN…)`,`Hacer copias de seguridad automáticas`,`Cifrar las columnas sensibles`,`Convertir tablas relacionales a documentos JSON`],c:0,exp:`Busca que cada dato se almacene una sola vez. A veces se desnormaliza puntualmente para ganar rendimiento en lecturas.`},
 {cat:'db',q:`¿Qué diferencia hay entre INNER JOIN y LEFT JOIN?`,o:[`INNER devuelve solo las coincidencias; LEFT añade además todas las filas de la tabla izquierda (con NULL si no casan)`,`LEFT elimina las filas sin coincidencia`,`INNER añade siempre las filas de la derecha con NULL`,`Son exactamente iguales`],c:0,exp:`Con LEFT JOIN, un pedido sin cliente asignado también aparecería en el resultado, con los campos del cliente a NULL.`},
 {cat:'db',q:`¿Qué trade-off introduce crear un índice en una tabla?`,o:[`Acelera las lecturas, pero ralentiza INSERT/UPDATE/DELETE y ocupa espacio extra`,`Acelera todo sin ningún coste`,`Solo acelera la PRIMARY KEY`,`Comprime la tabla a la mitad`],c:0,exp:`El índice (normalmente un árbol B) es una estructura auxiliar que el motor debe mantener actualizada en cada escritura.`},
 {cat:'db',q:`¿Qué es una inyección SQL y cómo se previene en Java?`,o:[`Código malicioso inyectado en consultas; se previene con PreparedStatement y parámetros`,`Un error de tipos; se previene con casts`,`Un bloqueo de tablas; se previene reiniciando el motor`,`Una fuga de memoria; se previene con System.gc()`],c:0,exp:`Nunca construyas SQL concatenando Strings con datos del usuario: usa PreparedStatement y stmt.setString(1, dato).`},
 {cat:'arq',q:`¿Qué principio SOLID dice "una clase debe estar abierta a extensión y cerrada a modificación"?`,o:[`OCP (Open/Closed Principle)`,`SRP (Single Responsibility)`,`ISP (Segregación de interfaces)`,`LSP (Sustitución de Liskov)`],c:0,exp:`Se añade comportamiento con clases nuevas (p. ej. estrategias o decoradores) sin tocar el código ya probado.`},
 {cat:'arq',q:`¿Qué es la inyección de dependencias?`,o:[`Un objeto recibe sus dependencias desde fuera en lugar de crearlas él mismo, favoreciendo el desacople`,`Crear las dependencias dentro del constructor`,`Un patrón para cifrar claves de BD`,`Inyectar código SQL en las consultas`],c:0,exp:`Facilita tests con mocks y bajo acoplamiento. Spring la aplica mediante su contenedor IoC (@Autowired, constructores…).`},
 {cat:'arq',q:`¿Qué caracteriza a una arquitectura de microservicios?`,o:[`Servicios pequeños, autónomos y desplegables de forma independiente que colaboran por red`,`Una única aplicación con todas las capas empaquetadas juntas`,`Todos los servicios compartiendo obligatoriamente la misma base de datos`,`Funciones ejecutadas dentro de un único main`],c:0,exp:`Ventajas: escalado y despliegue independientes. Costes: latencia de red, consistencia eventual y mayor necesidad de observabilidad.`},
 {cat:'arq',q:`¿Qué patrón define objetos suscritos que reaccionan automáticamente cuando el objeto observado cambia?`,o:[`Observer`,`Strategy`,`Decorator`,`Proxy`],c:0,exp:`Es la base de los sistemas de eventos y listeners: ActionListener en Swing, eventos en Spring, suscripciones en UI…`},
 {cat:'proj',q:`¿Qué es CI/CD?`,o:[`Integración y entrega/despliegue continuos: automatizar compilación, tests y despliegue`,`Un tipo de base de datos distribuida`,`Un patrón de diseño de clases`,`Un comando de Git para fusionar ramas`],c:0,exp:`Herramientas: Jenkins, GitHub Actions, GitLab CI. Ejecutar tests automáticos en cada push detecta errores mucho antes.`},
 {cat:'proj',q:`¿Qué diferencia principal hay entre git merge y git rebase?`,o:[`merge une ramas preservando el historial; rebase reescribe la historia colocando los commits sobre la rama base`,`rebase borra la rama de destino`,`merge nunca crea conflictos y rebase siempre`,`Son exactamente iguales`],c:0,exp:`Regla de oro: no hacer rebase sobre commits públicos ya compartidos con otras personas, porque reescribe el historial.`},
 {cat:'prog',q:`¿Qué diseño se considera deseable en los módulos de un sistema?`,o:[`Bajo acoplamiento y alta cohesión`,`Alto acoplamiento y baja cohesión`,`Alto acoplamiento y alta cohesión`,`Bajo acoplamiento y baja cohesión`],c:0,exp:`Cohesión: las responsabilidades internas del módulo están relacionadas. Acoplamiento: depender lo mínimo posible de módulos externos.`},
 {cat:'proj',q:`¿Qué es el principio DRY?`,o:[`Don't Repeat Yourself: evitar duplicar lógica centralizando el conocimiento en un solo lugar`,`Delete Redundant Years: podar código viejo`,`Un algoritmo de compresión de datos`,`Desplegar sin repetir pruebas manuales`],c:0,exp:`El código duplicado obliga a corregir el mismo bug en N sitios: extrae métodos, clases o módulos compartidos.`},
 {cat:'db',q:`¿Qué es una transacción en bases de datos?`,o:[`Una secuencia de operaciones que se ejecuta como una sola unidad atómica`,`Una copia de seguridad programada`,`Una tabla temporal de consulta`,`Un índice que acelera búsquedas`],c:0,exp:`BEGIN; ... COMMIT; o ROLLBACK. Si cualquier operación falla, todo se revierte para mantener la integridad.`},
 {cat:'arq',q:`¿Qué describe el patrón CQRS?`,o:[`Separar el modelo de lectura (queries) del de escritura (commands)`,`Unir lecturas y escrituras en un único modelo`,`Crear consultas con REST solamente`,`Cifrar la base de datos completa`],c:0,exp:`Command Query Responsibility Segregation separa los modelos: las lecturas pueden optimizarse con proyecciones o cachés sin contaminar el modelo de escritura.`},
 {cat:'java',q:`¿Cuál es la complejidad temporal promedio de buscar un elemento en un ArrayList no ordenado?`,o:[`O(1)`,`O(log n)`,`O(n)`,`O(n log n)`],c:2,exp:`Un ArrayList no ordenado exige un recorrido lineal (O(n)). HashSet/HashMap logran O(1) promedio gracias a la función hash.`},
 {cat:'java',q:`¿Qué garantiza la palabra clave volatile en un campo?`,o:[`Visibilidad entre hilos y orden happens-before, pero no atomicidad`,`Hace atómica la operación i++`,`Bloquea el acceso como synchronized`,`Impide que el campo sea null`],c:0,exp:`volatile asegura que una lectura vea siempre la última escritura y evita reordenamientos, pero una operación compuesta como i++ sigue sin ser atómica.`},
 {cat:'java',q:`¿Qué es un deadlock (interbloqueo)?`,o:[`Dos o más hilos se esperan mutuamente por candados que el otro posee y no avanzan`,`Un hilo termina por una excepción no capturada`,`El GC libera memoria de forma prematura`,`Un bucle infinito sin condición de salida`],c:0,exp:`Surge por espera circular de monitores (A→B y B→A). Se previene fijando un orden único de adquisición o usando tryLock con timeout.`},
 {cat:'java',q:`¿Qué devuelve Optional.of(null)?`,o:[`Un Optional vacío`,`Lanza NullPointerException`,`null`,`Un Optional con null interno`],c:1,exp:`of(null) lanza NPE. Para valores que pueden ser null se usa Optional.ofNullable(null), que devuelve Optional.empty().`},
 {cat:'java',q:`¿Cuál es la diferencia entre map() y flatMap() en un Stream?`,o:[`map transforma 1:1; flatMap transforma 1:N y aplana los Streams resultantes en uno solo`,`Son idénticos`,`map solo admite números y flatMap solo String`,`flatMap elimina los duplicados`],c:0,exp:`flatMap es útil con estructuras anidadas: lista.stream().flatMap(List::stream) une todos los elementos en un único Stream.`},
 {cat:'java',q:`¿Qué hace el JIT (Just-In-Time) en la JVM?`,o:[`Compila bytecode a código máquina nativo en tiempo de ejecución optimizando los puntos calientes`,`Interpreta el bytecode instrucción a instrucción`,`Recolecta los objetos sin referencias`,`Verifica la integridad del bytecode al cargarlo`],c:0,exp:`El JIT detecta código muy ejecutado (hot spots) y lo compila a nativo, logrando un rendimiento muy superior a la interpretación inicial.`},
 {cat:'java',q:`¿Qué hace la sentencia try-with-resources?`,o:[`Cierra automáticamente los recursos AutoCloseable al terminar el bloque`,`Captura todas las excepciones sin usar finally`,`Libera la memoria del heap`,`Evita tener que declarar catch`],c:0,exp:`try (FileReader r = new FileReader(f)) { ... } cierra el recurso al final o ante una excepción, en orden inverso al de apertura.`},
 {cat:'java',q:`¿Qué ocurre al ejecutar int x = Integer.MAX_VALUE; x++; ?`,o:[`x desborda y pasa a Integer.MIN_VALUE (overflow silencioso)`,`Lanza ArithmeticException`,`x permanece en Integer.MAX_VALUE`,`Se convierte automáticamente a long`],c:0,exp:`El overflow de enteros en Java es silencioso: MAX_VALUE+1 desborda al valor mínimo. Para detectarlo se usa Math.addExact, que lanza ArithmeticException.`},
 {cat:'java',q:`¿Cuál es la diferencia entre Lock y synchronized?`,o:[`Lock permite tryLock, timeout, múltiples condiciones y fairness; synchronized es un candado reentrante implícito`,`Son exactamente equivalentes`,`synchronized permite tryLock`,`Lock no existe en java.util.concurrent`],c:0,exp:`Lock (java.util.concurrent.locks) da control fino con tryLock, lockInterruptibly y newCondition; synchronized es más simple y libera el candado automáticamente al salir del bloque.`},
 {cat:'java',q:`¿Qué es un Record en Java (Java 16+)?`,o:[`Una clase final inmutable que declara sus componentes en el encabezado y genera equals, hashCode, toString y accesores`,`Una clase abstracta sin métodos`,`Un tipo para leer filas de base de datos`,`Un primitivo de 128 bits`],c:0,exp:`record Punto(int x, int y) {} genera automáticamente el constructor canónico, los accesores x()/y(), equals, hashCode y toString.`},
 {cat:'java',q:`¿Qué es el patrón de diseño Strategy?`,o:[`Define una familia de algoritmos intercambiables encapsulando cada uno`,`Crea una única instancia global`,`Añade responsabilidades dinámicamente a un objeto`,`Convierte una interfaz en otra`],c:0,exp:`Permite cambiar el comportamiento en tiempo de ejecución seleccionando una estrategia distinta, sin modificar el cliente.`},
 {cat:'java',q:`¿Qué es el patrón Decorator?`,o:[`Añade responsabilidades a un objeto dinámicamente envolviéndolo`,`Garantiza una única instancia`,`Separa la construcción de un objeto de su representación`,`Observa cambios de estado`],c:0,exp:`Envuelve un objeto en otro que añade comportamiento, respetando la misma interfaz, sin modificar el original.`},
 {cat:'java',q:`¿Qué problema resuelve el patrón Singleton?`,o:[`Garantizar una única instancia con acceso global`,`Permitir múltiples instancias`,`Desacoplar el cliente de las clases concretas`,`Aplanar colecciones anidadas`],c:0,exp:`Constructor privado y método estático que devuelve siempre la misma instancia. Útil para configuraciones o pools.`},
 {cat:'java',q:`¿Qué es una expresión lambda en Java?`,o:[`Una función anónima que implementa una interfaz funcional`,`Una variable de clase`,`Un tipo primitivo`,`Una anotación de compilación`],c:0,exp:`(a, b) -> a + b implementa el único método abstracto de la interfaz funcional de forma concisa.`},
 {cat:'java',q:`¿Qué hace el método default en una interfaz?`,o:[`Proporciona una implementación por defecto que las clases pueden usar o sobrescribir`,`Impide implementar la interfaz`,`Hace la interfaz final`,`Convierte la interfaz en clase`],c:0,exp:`Los métodos default permiten añadir funcionalidad a interfaces sin romper las implementaciones existentes.`},
 {cat:'java',q:`¿Qué es el box/unboxing en Java?`,o:[`Conversión automática entre primitivos y wrappers`,`Encapsular clases en paquetes`,`Convertir String a int`,`Comprimir archivos .class`],c:0,exp:`autoboxing: int → Integer; unboxing: Integer → int. El compilador lo inserta automáticamente.`},
 {cat:'db',q:`¿Qué es un índice compuesto en SQL?`,o:[`Un índice que abarca varias columnas`,`Un índice sobre una sola columna`,`Una clave primaria duplicada`,`Un backup de la tabla`],c:0,exp:`CREATE INDEX idx ON t(a, b); optimiza consultas que filtran por esas columnas en el orden del índice.`},
 {cat:'db',q:`¿Qué significa la restricción UNIQUE?`,o:[`No admite valores duplicados en la columna`,`Permite valores NULL ilimitados`,`Crea una clave foránea`,`Borra filas automáticamente`],c:0,exp:`UNIQUE garantiza unicidad; a diferencia de PRIMARY KEY, permite NULL (en muchos motores, uno solo).`},
 {cat:'db',q:`¿Qué hace el comando SQL TRUNCATE?`,o:[`Vacía la tabla conservando su estructura`,`Borra la tabla completa`,`Elimina filas según condición`,`Modifica la estructura`],c:0,exp:`TRUNCATE TABLE t; borra todas las filas rápido; no permite WHERE y, en muchos motores, no se puede deshacer.`},
 {cat:'arq',q:`¿Qué es la escalabilidad horizontal?`,o:[`Añadir más máquinas para repartir la carga`,`Aumentar la CPU/RAM de una sola máquina`,`Comprimir la base de datos`,`Cifrar el tráfico`],c:0,exp:`Escalar horizontalmente añade nodos; verticalmente mejora el hardware de uno solo.`},
 {cat:'arq',q:`¿Qué es la latencia en sistemas distribuidos?`,o:[`El tiempo que tarda una petición en ir y volver`,`La cantidad de datos almacenados`,`El número de servidores`,`La velocidad de compilación`],c:0,exp:`La latencia mide el retraso de red; es crítica en microservicios por las múltiples llamadas entre servicios.`},
 {cat:'arq',q:`¿Qué es el acoplamiento en arquitectura de software?`,o:[`El grado de dependencia entre módulos`,`La cohesión interna de un módulo`,`La velocidad de despliegue`,`El número de tests`],c:0,exp:`Bajo acoplamiento significa que un cambio en un módulo no obliga a cambiar otros.`},
 {cat:'prog',q:`¿Qué es la programación funcional?`,o:[`Un paradigma basado en funciones puras, inmutabilidad y composición`,`Un estilo con clases y herencia`,`Una técnica de optimización de bucles`,`Un tipo de base de datos`],c:0,exp:`Evita estado mutable y efectos secundarios, favoreciendo funciones que solo dependen de sus entradas.`},
 {cat:'prog',q:`¿Qué es una estructura de datos árbol binario?`,o:[`Una jerarquía donde cada nodo tiene hasta dos hijos`,`Una secuencia lineal`,`Un mapa clave-valor`,`Un grafo cíclico`],c:0,exp:`En un árbol binario cada nodo tiene hijo izquierdo y derecho; base de BST, heaps y árboles balanceados.`},
 {cat:'prog',q:`¿Qué es un grafo en estructuras de datos?`,o:[`Un conjunto de nodos conectados por aristas`,`Una lista ordenada`,`Una pila LIFO`,`Una tabla hash`],c:0,exp:`Los grafos modelan relaciones arbitrarias; se recorren con BFS o DFS y resuelven rutas, redes y dependencias.`},
 {cat:'proj',q:`¿Qué es una rama (branch) en Git?`,o:[`Una línea independiente de desarrollo que diverge del historial principal`,`Una copia de seguridad`,`Un archivo de configuración`,`Un commit borrado`],c:0,exp:`Las ramas permiten trabajar en paralelo; luego se integran con merge o rebase.`},
 {cat:'proj',q:`¿Qué es un merge conflict en Git?`,o:[`Cuando dos ramas modifican las mismas líneas y Git no puede fusionarlas automáticamente`,`Un error de red al hacer push`,`Una rama eliminada`,`Un commit duplicado`],c:0,exp:`Los conflictos se resuelven manualmente eligiendo qué cambios conservar antes de completar el merge.`},
 {cat:'java',q:`¿Qué hace el método intern() de String?`,o:[`Devuelve la referencia canónica del String en el pool de literales`,`Invierte el orden de los caracteres`,`Convierte a mayúsculas`,`Divide el String en un array`],c:0,exp:`intern() busca o añade la cadena al pool, permitiendo comparar con == en casos concretos.`},
 {cat:'java',q:`¿Qué es un daemon thread?`,o:[`Un hilo en segundo plano que no impide que la JVM termine`,`Un hilo de máxima prioridad`,`Un hilo que no puede bloquearse`,`Un proceso separado del sistema`],c:0,exp:`La JVM termina cuando solo quedan hilos daemon. Se marcan con setDaemon(true) antes de start().`},
 {cat:'java',q:`¿Qué es la condición de carrera (race condition)?`,o:[`Dos hilos acceden a datos compartidos sin sincronización y el resultado depende del orden de ejecución`,`Un tipo de excepción`,`Una optimización del JIT`,`Un patrón de diseño`],c:0,exp:`Se produce cuando el resultado depende de la planificación de hilos; se evita con synchronized, Lock o estructuras atómicas.`},
 {cat:'java',q:`¿Qué es un Stream paralelo en Java?`,o:[`Un Stream que procesa elementos en múltiples hilos mediante parallelStream()`,`Un Stream que solo lee archivos`,`Un Stream inmutable`,`Un Stream ordenado alfabéticamente`],c:0,exp:`parallelStream() divide el trabajo entre hilos; no siempre es más rápido y exige operaciones seguras.`},
 {cat:'java',q:`¿Qué clase se usa para operaciones atómicas sobre int?`,o:[`AtomicInteger`,`Integer`,`BigInteger`,`SynchronizedInt`],c:0,exp:`AtomicInteger ofrece métodos como incrementAndGet() y compareAndSet() sin bloqueos explícitos.`},
 {cat:'java',q:`¿Qué es el classpath en Java?`,o:[`La ruta donde la JVM y el compilador buscan las clases`,`El directorio de instalación del JDK`,`La carpeta temporal del sistema`,`El archivo de configuración del IDE`],c:0,exp:`Se define con -cp o CLASSPATH e indica dónde buscar .class y .jar al compilar o ejecutar.`},
 {cat:'db',q:`¿Qué es una vista (VIEW) en SQL?`,o:[`Una consulta almacenada con nombre que se usa como tabla virtual`,`Una copia física de la tabla`,`Un índice de búsqueda`,`Un trigger automático`],c:0,exp:`CREATE VIEW v AS SELECT ...; simplifica consultas y restringe columnas, sin duplicar datos.`},
 {cat:'db',q:`¿Qué es un procedimiento almacenado?`,o:[`Código SQL reutilizable almacenado en la base de datos`,`Una tabla temporal`,`Un índice compuesto`,`Una restricción de clave`],c:0,exp:`Permite encapsular lógica en la BD, reducir tráfico y reutilizar operaciones frecuentes.`},
 {cat:'db',q:`¿Qué es una migración de base de datos?`,o:[`Un cambio de esquema versionado y reproducible`,`Una copia de los datos`,`Un backup incremental`,`Un tipo de índice`],c:0,exp:`Herramientas como Flyway o Liquibase aplican migraciones en orden para mantener el esquema consistente.`},
 {cat:'db',q:`¿Qué significa OLTP?`,o:[`Online Transaction Processing: sistemas transaccionales de alta concurrencia`,`Online Long Time Process`,`Object Language Test Protocol`,`Open Line Transfer Program`],c:0,exp:`OLTP se centra en muchas transacciones cortas (pedidos, reservas); OLAP analiza grandes volúmenes.`},
 {cat:'arq',q:`¿Qué es un API Gateway?`,o:[`Un punto único de entrada que enruta peticiones a los servicios backend`,`Una base de datos central`,`Un framework de frontend`,`Un protocolo de mensajería`],c:0,exp:`Centraliza autenticación, enrutado, límites de tasa y agregación de respuestas en arquitecturas de microservicios.`},
 {cat:'arq',q:`¿Qué es el eventual consistency?`,o:[`Los datos convergen a un estado consistente tras un tiempo, sin bloqueos inmediatos`,`Garantiza consistencia inmediata en cada lectura`,`Un tipo de backup`,`Un algoritmo de compresión`],c:0,exp:`En sistemas distribuidos, replicar datos puede producir lecturas temporalmente desactualizadas que acaban convergiendo.`},
 {cat:'arq',q:`¿Qué es un balanceador de carga?`,o:[`Distribuye el tráfico entrante entre varios servidores`,`Almacena sesiones de usuario`,`Cifra las contraseñas`,`Compila el código`],c:0,exp:`Reparte peticiones para evitar sobrecargar un nodo y aporta tolerancia a fallos.`},
 {cat:'prog',q:`¿Qué es una cola de mensajes?`,o:[`Un buffer asíncrono que desacopla productores y consumidores`,`Una lista enlazada síncrona`,`Un tipo de dato primitivo`,`Un patrón de UI`],c:0,exp:`Kafka, RabbitMQ o SQS permiten comunicación asíncrona y tolerancia a picos de carga.`},
 {cat:'prog',q:`¿Qué es un dead code (código muerto)?`,o:[`Código que nunca se ejecuta porque no es alcanzable o nadie lo llama`,`Código con bugs`,`Código sin comentarios`,`Código demasiado optimizado`],c:0,exp:`Debe eliminarse para reducir complejidad y evitar confusión; los linters y el análisis estático lo detectan.`},
 {cat:'proj',q:`¿Qué es un pipeline de CI?`,o:[`Una secuencia automatizada de pasos que compila, prueba y empaqueta el código`,`Un servidor de producción`,`Un repositorio de artefactos`,`Una rama protegida`],c:0,exp:`Se dispara en cada push y ejecuta build, tests y análisis para detectar regresiones temprano.`},
 {cat:'proj',q:`¿Qué es un commit atómico?`,o:[`Un commit que agrupa cambios de una única unidad lógica`,`Un commit que borra el historial`,`Un commit firmado digitalmente`,`Un commit en otra rama`],c:0,exp:`Cada commit debe resolver una sola responsabilidad para facilitar revisión y revertir cambios con seguridad.`}
];
